SELECT EXISTS(
  SELECT 1
  FROM ai_chat_session_participant
  WHERE workspace_id = #{workspaceId}
    AND session_id = #{sessionId}
    AND user_id = #{userId}
)

SELECT COALESCE(MAX(seq), 0) + 1
FROM ai_chat_message
WHERE workspace_id = #{workspaceId}
  AND session_id = #{sessionId}

